insert into public.learning_content
(content_id,faculty,subject,content_type,access_tier,display_order,content_data,is_published)
values
('bmlt-biochem2-mcq-001','BMLT','BMLT NHPC Licensing','mcq','free',1,'{"question":"Which enzyme catalyzes the conversion of starch into maltose during digestion?","translation":"पाचनमा starch लाई maltose मा बदल्ने enzyme कुन हो?","options":["Amylase","Pepsin","Trypsin","Lactase"],"correctIndex":0,"explanation":"Amylase hydrolyzes starch into smaller carbohydrates, including maltose.","explanationNe":"Amylase ले starch hydrolysis गरी maltose लगायत साना carbohydrate बनाउँछ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mcq-002','BMLT','BMLT NHPC Licensing','mcq','free',2,'{"question":"Which enzyme is commonly increased in hepatocellular injury?","translation":"Hepatocellular injury मा कुन enzyme प्रायः बढ्छ?","options":["ALT","ALP only","Amylase","CK"],"correctIndex":0,"explanation":"ALT is a useful marker of hepatocellular injury, interpreted with other results.","explanationNe":"ALT hepatocellular injury को उपयोगी marker हो; अन्य result सँगै व्याख्या गरिन्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mcq-003','BMLT','BMLT NHPC Licensing','mcq','free',3,'{"question":"AST is also present in significant amounts in:","translation":"AST पर्याप्त मात्रामा अर्को कुन tissue मा पनि हुन्छ?","options":["Skeletal and cardiac muscle","Only bile ducts","Only pancreas","Only red cell membrane"],"correctIndex":0,"explanation":"AST occurs in liver, heart and skeletal muscle, so it is less liver-specific than ALT.","explanationNe":"AST liver, heart र skeletal muscle मा हुन्छ, त्यसैले ALT भन्दा कम liver-specific छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mcq-004','BMLT','BMLT NHPC Licensing','mcq','free',4,'{"question":"Which enzyme is often elevated in alcoholic liver disease and cholestasis?","translation":"Alcoholic liver disease र cholestasis मा कुन enzyme बढ्न सक्छ?","options":["GGT","CK","LDH-1 only","Cholinesterase"],"correctIndex":0,"explanation":"GGT can rise in hepatobiliary disease and with alcohol exposure; it is not diagnostic alone.","explanationNe":"GGT hepatobiliary disease र alcohol exposure मा बढ्न सक्छ; एक्लै diagnosis गर्दैन।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mcq-005','BMLT','BMLT NHPC Licensing','mcq','free',5,'{"question":"Direct bilirubin is another name for:","translation":"Direct bilirubin लाई अर्को के भनिन्छ?","options":["Conjugated bilirubin","Unconjugated bilirubin","Delta glucose","Urobilinogen"],"correctIndex":0,"explanation":"Direct bilirubin is mainly conjugated bilirubin measured by the assay.","explanationNe":"Direct bilirubin मुख्यतः assay ले मापन गर्ने conjugated bilirubin हो।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mcq-006','BMLT','BMLT NHPC Licensing','mcq','free',6,'{"question":"Which urine finding may increase in obstructive jaundice?","translation":"Obstructive jaundice मा urine मा कुन पदार्थ बढ्न सक्छ?","options":["Bilirubin","Urobilinogen always markedly increased","Glucose in every case","Ketone only"],"correctIndex":0,"explanation":"Conjugated bilirubin is water-soluble and may appear in urine when bile flow is obstructed.","explanationNe":"Conjugated bilirubin पानीमा घुल्ने भएकाले bile flow अवरुद्ध हुँदा urine मा देखिन सक्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mcq-007','BMLT','BMLT NHPC Licensing','mcq','free',7,'{"question":"Ammonia is converted to urea mainly to:","translation":"Ammonia लाई urea मा बदल्नुको मुख्य उद्देश्य के हो?","options":["Reduce toxicity and allow excretion","Store oxygen","Digest protein in stomach","Produce bile pigment"],"correctIndex":0,"explanation":"The hepatic urea cycle detoxifies ammonia for renal excretion.","explanationNe":"Liver को urea cycle ले ammonia detoxify गरी kidney बाट excretion गर्न मद्दत गर्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mcq-008','BMLT','BMLT NHPC Licensing','mcq','free',8,'{"question":"Which test is commonly used to assess glomerular filtration indirectly?","translation":"Glomerular filtration अप्रत्यक्ष मूल्यांकन गर्न कुन test प्रयोग हुन्छ?","options":["Serum creatinine/eGFR","Serum bilirubin","Serum amylase","Serum ALP"],"correctIndex":0,"explanation":"Creatinine-based eGFR estimates kidney filtration, with limitations in some patients.","explanationNe":"Creatinine आधारित eGFR ले kidney filtration अनुमान गर्छ, केही अवस्थामा सीमितता हुन्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mcq-009','BMLT','BMLT NHPC Licensing','mcq','free',9,'{"question":"A low serum albumin may contribute to:","translation":"Serum albumin कम हुँदा कुन समस्या हुन सक्छ?","options":["Edema","Hypercalcemia in every case","High oxygen saturation","Increased clotting factor synthesis"],"correctIndex":0,"explanation":"Reduced oncotic pressure from low albumin can favor fluid movement into tissues.","explanationNe":"Albumin कम हुँदा oncotic pressure घटेर tissue मा fluid जम्न सक्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mcq-010','BMLT','BMLT NHPC Licensing','mcq','free',10,'{"question":"Which protein transports iron in plasma?","translation":"Plasma मा iron transport गर्ने protein कुन हो?","options":["Transferrin","Albumin exclusively","Haptoglobin","Ceruloplasmin"],"correctIndex":0,"explanation":"Transferrin binds and transports iron through the circulation.","explanationNe":"Transferrin ले iron bind गरी circulation मा transport गर्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mcq-011','BMLT','BMLT NHPC Licensing','mcq','free',11,'{"question":"Which protein binds free hemoglobin released into plasma?","translation":"Plasma मा निस्केको free hemoglobin कुन protein ले bind गर्छ?","options":["Haptoglobin","Transferrin","Albumin only","Prealbumin"],"correctIndex":0,"explanation":"Haptoglobin binds free hemoglobin; levels may fall during intravascular hemolysis.","explanationNe":"Haptoglobin free hemoglobin bind गर्छ; intravascular hemolysis मा घट्न सक्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mcq-012','BMLT','BMLT NHPC Licensing','mcq','free',12,'{"question":"Ceruloplasmin primarily transports:","translation":"Ceruloplasmin मुख्यतः के transport गर्छ?","options":["Copper","Iron only","Calcium","Sodium"],"correctIndex":0,"explanation":"Ceruloplasmin is a major copper-carrying protein in plasma.","explanationNe":"Ceruloplasmin plasma को प्रमुख copper-carrying protein हो।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mcq-013','BMLT','BMLT NHPC Licensing','mcq','free',13,'{"question":"Which mineral is a component of hemoglobin heme?","translation":"Hemoglobin heme को component कुन mineral हो?","options":["Iron","Zinc","Copper","Iodine"],"correctIndex":0,"explanation":"Iron in heme reversibly binds oxygen.","explanationNe":"Heme मा भएको iron ले oxygen लाई reversible रूपमा bind गर्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mcq-014','BMLT','BMLT NHPC Licensing','mcq','free',14,'{"question":"A low ferritin with microcytic anemia most strongly supports:","translation":"Microcytic anemia सँग ferritin कम हुँदा कुन अवस्था बढी सम्भावित हुन्छ?","options":["Iron deficiency","Vitamin B12 deficiency","Acute hemolysis only","Folate excess"],"correctIndex":0,"explanation":"Low ferritin strongly supports depleted iron stores.","explanationNe":"Ferritin कम हुनु iron store घटेको बलियो संकेत हो।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mcq-015','BMLT','BMLT NHPC Licensing','mcq','free',15,'{"question":"Which analyte may be falsely decreased if a sample is exposed to light?","translation":"Sample लाई light मा राख्दा कुन analyte झूटो घट्न सक्छ?","options":["Bilirubin","Sodium","Creatinine","Urea"],"correctIndex":0,"explanation":"Bilirubin is light-sensitive and should be protected from prolonged light exposure.","explanationNe":"Bilirubin light-sensitive हुन्छ; लामो समय light बाट जोगाउनुपर्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mcq-016','BMLT','BMLT NHPC Licensing','mcq','free',16,'{"question":"Which sample condition can cause falsely low glucose if processing is delayed?","translation":"Processing ढिला हुँदा कुन sample condition ले glucose झूटो घटाउन सक्छ?","options":["Continued cellular glycolysis","Immediate separation","Correct fluoride tube handling","Prompt analysis"],"correctIndex":0,"explanation":"Blood cells continue consuming glucose until separated or glycolysis is inhibited.","explanationNe":"Cells छुट्याउन वा glycolysis रोक्नुअघि blood cells ले glucose प्रयोग गरिरहन्छन्।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mcq-017','BMLT','BMLT NHPC Licensing','mcq','free',17,'{"question":"Sodium fluoride in a gray-top tube is used mainly to:","translation":"Gray-top tube मा sodium fluoride मुख्यतः किन हुन्छ?","options":["Inhibit glycolysis","Activate clotting","Chelate all proteins","Preserve bilirubin from light"],"correctIndex":0,"explanation":"Fluoride inhibits glycolysis and helps preserve glucose, though early glycolysis may continue.","explanationNe":"Fluoride ले glycolysis रोक्न मद्दत गर्छ, तर सुरुमा केही glycolysis जारी रहन सक्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mcq-018','BMLT','BMLT NHPC Licensing','mcq','free',18,'{"question":"Which anticoagulant is generally unsuitable for routine calcium measurement?","translation":"Routine calcium measurement का लागि कुन anticoagulant उपयुक्त हुँदैन?","options":["EDTA","Heparin in suitable plasma assays","None, serum is commonly used","Lithium heparin when validated"],"correctIndex":0,"explanation":"EDTA chelates calcium and can produce falsely low calcium results.","explanationNe":"EDTA ले calcium chelate गर्छ र result झूटो कम आउन सक्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mcq-019','BMLT','BMLT NHPC Licensing','mcq','free',19,'{"question":"A hemolyzed specimen may show increased LDH because:","translation":"Hemolyzed sample मा LDH बढ्नुको कारण के हो?","options":["Red cells contain LDH released on lysis","LDH is destroyed by red cells","Hemolysis removes all enzymes","LDH is made only in serum"],"correctIndex":0,"explanation":"Cell disruption releases intracellular LDH into the specimen.","explanationNe":"Cell फुट्दा intracellular LDH sample मा निस्कन्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mcq-020','BMLT','BMLT NHPC Licensing','mcq','free',20,'{"question":"Which quality-control rule flags a single control result beyond 3 SD?","translation":"एक control result 3 SD भन्दा बाहिर हुँदा कुन QC rule लागू हुन्छ?","options":["1-3s","1-2s","2-2s","R-4s"],"correctIndex":0,"explanation":"The 1-3s rule is a rejection rule when one control exceeds ±3 SD.","explanationNe":"एक control ±3 SD भन्दा बाहिर भए 1-3s rule rejection rule हो।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mcq-021','BMLT','BMLT NHPC Licensing','mcq','free',21,'{"question":"A systematic analytical error mainly causes:","translation":"Systematic analytical error ले मुख्यतः के गराउँछ?","options":["Consistent bias from the true value","Random scatter only","No change in results","Only specimen mislabeling"],"correctIndex":0,"explanation":"Systematic error shifts results in a consistent direction or magnitude.","explanationNe":"Systematic error ले result लाई लगातार एक दिशामा shift गर्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mcq-022','BMLT','BMLT NHPC Licensing','mcq','free',22,'{"question":"Precision refers to:","translation":"Precision भन्नाले के बुझिन्छ?","options":["Closeness of repeated results to one another","Closeness to the true value only","Sensitivity to disease","Sample volume"],"correctIndex":0,"explanation":"Precision describes repeatability; accuracy describes closeness to the true value.","explanationNe":"Precision ले repeatability जनाउँछ; accuracy ले true value नजिक हुनु जनाउँछ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mcq-023','BMLT','BMLT NHPC Licensing','mcq','free',23,'{"question":"A reference interval usually includes approximately what proportion of a healthy reference population?","translation":"Reference interval ले स्वस्थ reference population को लगभग कति हिस्सा समेट्छ?","options":["95%","50%","68%","100%"],"correctIndex":0,"explanation":"A conventional central reference interval is often defined as the 2.5th to 97.5th percentiles.","explanationNe":"सामान्य central reference interval प्रायः 2.5th देखि 97.5th percentile सम्म हुन्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mcq-024','BMLT','BMLT NHPC Licensing','mcq','free',24,'{"question":"Analytical sensitivity is commonly related to the ability to detect:","translation":"Analytical sensitivity कुन क्षमता सँग सम्बन्धित छ?","options":["Small amounts of analyte","Only high concentrations","Patient symptoms","Sample color"],"correctIndex":0,"explanation":"Sensitivity concerns detection of low analyte concentrations, including the detection limit.","explanationNe":"Sensitivity ले कम analyte concentration detect गर्ने क्षमता जनाउँछ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mcq-025','BMLT','BMLT NHPC Licensing','mcq','free',25,'{"question":"A high analytical specificity means the method:","translation":"Analytical specificity उच्च हुनुको अर्थ के हो?","options":["Measures the intended analyte with minimal interference","Detects every disease","Always has zero error","Needs no calibration"],"correctIndex":0,"explanation":"Specificity describes ability to measure the target without significant interference from other substances.","explanationNe":"Specificity ले अन्य पदार्थको interference कम राखी target मापन गर्ने क्षमता जनाउँछ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mcq-026','BMLT','BMLT NHPC Licensing','mcq','free',26,'{"question":"The SI unit commonly used for glucose concentration in many countries is:","translation":"धेरै देशमा glucose concentration को SI unit कुन हो?","options":["mmol/L","mg/dL only","g/dL","IU/L"],"correctIndex":0,"explanation":"Glucose is commonly reported in mmol/L in SI-based reporting; mg/dL is also widely used.","explanationNe":"SI reporting मा glucose प्रायः mmol/L हुन्छ; mg/dL पनि व्यापक छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mock-001','BMLT','BMLT NHPC Licensing','mock','free',1,'{"question":"To convert glucose from mg/dL to mmol/L, approximately multiply by:","translation":"Glucose mg/dL बाट mmol/L मा बदल्न लगभग कुन factor ले गुणा गर्ने?","options":["0.0555","10","18","100"],"correctIndex":0,"explanation":"For glucose, mmol/L is approximately mg/dL multiplied by 0.0555.","explanationNe":"Glucose का लागि mmol/L ≈ mg/dL × 0.0555 हुन्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mock-002','BMLT','BMLT NHPC Licensing','mock','free',2,'{"question":"Which enzyme is measured in the glucose oxidase method?","translation":"Glucose oxidase method मा कुन enzyme प्रयोग हुन्छ?","options":["Glucose oxidase","Urease","Peroxidase only as analyte","Pepsin"],"correctIndex":0,"explanation":"Glucose oxidase oxidizes glucose; coupled reactions generate a measurable signal.","explanationNe":"Glucose oxidase ले glucose oxidize गर्छ र coupled reaction बाट measurable signal आउँछ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mock-003','BMLT','BMLT NHPC Licensing','mock','free',3,'{"question":"The Jaffe reaction is used in many methods to measure:","translation":"Jaffe reaction धेरै method मा कुन मापन गर्न प्रयोग हुन्छ?","options":["Creatinine","Bilirubin","Albumin","Glucose"],"correctIndex":0,"explanation":"Creatinine reacts with alkaline picrate in the Jaffe method, with known interferences.","explanationNe":"Jaffe method मा creatinine alkaline picrate सँग react गर्छ; interference हुन सक्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mock-004','BMLT','BMLT NHPC Licensing','mock','free',4,'{"question":"Which method principle is used in many immunoassays to detect antigen or antibody?","translation":"धेरै immunoassay मा antigen वा antibody detect गर्न कुन principle प्रयोग हुन्छ?","options":["Specific antigen-antibody binding","Gram staining","Electrophoretic mobility only","Flame emission only"],"correctIndex":0,"explanation":"Immunoassays use specific immune binding with a measurable label or signal.","explanationNe":"Immunoassay ले specific antigen-antibody binding र measurable signal प्रयोग गर्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mock-005','BMLT','BMLT NHPC Licensing','mock','free',5,'{"question":"A sandwich immunoassay is generally suited to measure:","translation":"Sandwich immunoassay सामान्यतया के मापन गर्न उपयुक्त हुन्छ?","options":["Antigens with multiple binding sites","Only sodium ions","Only small molecules without modification","Cell count directly"],"correctIndex":0,"explanation":"A sandwich format captures analyte between two antibodies and commonly measures larger antigens.","explanationNe":"Sandwich format मा analyte दुई antibody बीच capture हुन्छ, प्रायः ठूला antigen मापन हुन्छन्।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mock-006','BMLT','BMLT NHPC Licensing','mock','free',6,'{"question":"In competitive immunoassay, increasing analyte concentration often causes signal to:","translation":"Competitive immunoassay मा analyte बढ्दा signal प्रायः के हुन्छ?","options":["Decrease","Increase without limit","Remain always identical","Become a cell count"],"correctIndex":0,"explanation":"In many competitive formats, patient analyte competes with labeled analyte, reducing signal.","explanationNe":"धेरै competitive format मा patient analyte ले labeled analyte सँग compete गर्दा signal घट्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mock-007','BMLT','BMLT NHPC Licensing','mock','free',7,'{"question":"Which hormone is commonly elevated in primary hyperparathyroidism with hypercalcemia?","translation":"Hypercalcemia भएको primary hyperparathyroidism मा कुन hormone बढ्छ?","options":["PTH","TSH","Insulin","Calcitonin always suppressed to zero"],"correctIndex":0,"explanation":"Primary hyperparathyroidism typically produces elevated or inappropriately normal PTH with high calcium.","explanationNe":"Primary hyperparathyroidism मा calcium उच्च हुँदा PTH बढेको वा अनुचित रूपमा normal हुन्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mock-008','BMLT','BMLT NHPC Licensing','mock','free',8,'{"question":"In primary hyperaldosteronism, which electrolyte pattern may occur?","translation":"Primary hyperaldosteronism मा कुन electrolyte pattern हुन सक्छ?","options":["Low potassium and metabolic alkalosis","High potassium and acidosis","Low sodium always","High calcium only"],"correctIndex":0,"explanation":"Aldosterone promotes sodium retention and potassium/hydrogen loss.","explanationNe":"Aldosterone ले sodium retention र potassium/hydrogen loss बढाउँछ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mock-009','BMLT','BMLT NHPC Licensing','mock','free',9,'{"question":"Which thyroid test is often the first-line screening test for primary thyroid dysfunction?","translation":"Primary thyroid dysfunction को first-line screening test कुन हो?","options":["TSH","Total bilirubin","Serum amylase","CK"],"correctIndex":0,"explanation":"TSH is commonly used as an initial test, with free T4 added based on results and context.","explanationNe":"TSH प्रारम्भिक test हो; result र context अनुसार free T4 थपिन्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mock-010','BMLT','BMLT NHPC Licensing','mock','free',10,'{"question":"A low TSH with elevated free T4 most often suggests:","translation":"TSH कम र free T4 बढेको अवस्थामा प्रायः के संकेत हुन्छ?","options":["Primary hyperthyroidism","Primary hypothyroidism","Iron deficiency","Renal stone"],"correctIndex":0,"explanation":"Excess thyroid hormone suppresses pituitary TSH in primary hyperthyroidism.","explanationNe":"Primary hyperthyroidism मा thyroid hormone बढ्दा pituitary TSH दबिन्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mock-011','BMLT','BMLT NHPC Licensing','mock','free',11,'{"question":"Which test is useful for evaluating vitamin B12 deficiency?","translation":"Vitamin B12 deficiency मूल्यांकन गर्न कुन test उपयोगी हुन्छ?","options":["Serum vitamin B12","Serum sodium only","ALP only","Urine glucose"],"correctIndex":0,"explanation":"Serum B12 is commonly measured; methylmalonic acid may help in equivocal cases.","explanationNe":"Serum B12 मापन गरिन्छ; अस्पष्ट अवस्थामा methylmalonic acid उपयोगी हुन सक्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mock-012','BMLT','BMLT NHPC Licensing','mock','free',12,'{"question":"Folate deficiency typically causes which red-cell pattern?","translation":"Folate deficiency ले सामान्यतया कुन red-cell pattern गराउँछ?","options":["Macrocytosis/megaloblastic anemia","Microcytosis always","Spherocytosis only","No change in cell size"],"correctIndex":0,"explanation":"Folate deficiency impairs DNA synthesis and can cause megaloblastic macrocytic anemia.","explanationNe":"Folate कमीले DNA synthesis बिगारेर megaloblastic macrocytic anemia गराउन सक्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mock-013','BMLT','BMLT NHPC Licensing','mock','free',13,'{"question":"Which analyte is often measured to assess bone turnover or cholestatic enzyme activity?","translation":"Bone turnover वा cholestatic enzyme activity मूल्यांकन गर्न कुन analyte मापन गरिन्छ?","options":["ALP","Troponin I","HbA1c","C-peptide"],"correctIndex":0,"explanation":"ALP has bone and hepatobiliary sources, so isoenzymes or GGT may help interpret it.","explanationNe":"ALP bone र hepatobiliary दुवैबाट आउँछ; isoenzyme वा GGT व्याख्यामा सहयोगी हुन्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mock-014','BMLT','BMLT NHPC Licensing','mock','free',14,'{"question":"Which condition can increase serum uric acid?","translation":"कुन अवस्थाले serum uric acid बढाउन सक्छ?","options":["Reduced renal excretion or increased purine breakdown","Low purine turnover always","Hypoglycemia only","Low albumin alone"],"correctIndex":0,"explanation":"Uric acid rises with impaired excretion, increased production, or both.","explanationNe":"Excretion कम वा production बढी हुँदा uric acid बढ्न सक्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mock-015','BMLT','BMLT NHPC Licensing','mock','free',15,'{"question":"Lactate may be elevated in tissue hypoperfusion because of increased:","translation":"Tissue hypoperfusion मा lactate बढ्नुको कारण के हो?","options":["Anaerobic glycolysis","Protein synthesis","Bile formation","Urea filtration"],"correctIndex":0,"explanation":"When oxygen delivery is inadequate, lactate production may rise; clinical context is essential.","explanationNe":"Oxygen delivery कम हुँदा lactate production बढ्न सक्छ; clinical context आवश्यक छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mock-016','BMLT','BMLT NHPC Licensing','mock','free',16,'{"question":"Which blood gas value directly reflects the partial pressure of dissolved oxygen?","translation":"Blood gas मा dissolved oxygen को partial pressure कुन value ले देखाउँछ?","options":["PaO2","PaCO2","HCO3−","Base excess"],"correctIndex":0,"explanation":"PaO2 measures oxygen partial pressure in arterial blood.","explanationNe":"PaO2 ले arterial blood मा oxygen को partial pressure मापन गर्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mock-017','BMLT','BMLT NHPC Licensing','mock','free',17,'{"question":"A raised PaCO2 with low pH indicates:","translation":"PaCO2 बढेको र pH कम भएको अवस्थामा के संकेत हुन्छ?","options":["Respiratory acidosis","Respiratory alkalosis","Metabolic alkalosis","Normal acid-base balance"],"correctIndex":0,"explanation":"CO2 retention increases acidity and lowers pH.","explanationNe":"CO2 जम्मा हुँदा acidity बढेर pH घट्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mock-018','BMLT','BMLT NHPC Licensing','mock','free',18,'{"question":"Which parameter is most affected by prolonged tourniquet application and fist clenching?","translation":"Tourniquet लामो समय लगाउँदा र fist clench गर्दा कुन parameter प्रभावित हुन सक्छ?","options":["Potassium and some protein-bound analytes","Only bilirubin","Only TSH","No laboratory parameter"],"correctIndex":0,"explanation":"Stasis and muscle activity can alter potassium and several concentration-dependent analytes.","explanationNe":"Stasis र muscle activity ले potassium तथा केही concentration-dependent analyte बदल्न सक्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mock-019','BMLT','BMLT NHPC Licensing','mock','free',19,'{"question":"Which tube additive is commonly used for plasma chemistry tests when validated?","translation":"Validated plasma chemistry test मा कुन tube additive सामान्यतया प्रयोग हुन्छ?","options":["Lithium heparin","EDTA for calcium","Sodium citrate for every analyte","No additive in all cases"],"correctIndex":0,"explanation":"Lithium heparin plasma is widely used for many chemistry assays, depending on method.","explanationNe":"Lithium heparin plasma धेरै chemistry assay मा प्रयोग हुन्छ, method अनुसार।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mock-020','BMLT','BMLT NHPC Licensing','mock','free',20,'{"question":"Which analyte is generally measured in a 2-hour oral glucose tolerance test?","translation":"2-hour oral glucose tolerance test मा कुन analyte मापन गरिन्छ?","options":["Plasma glucose","Serum calcium","Serum albumin","Serum CK"],"correctIndex":0,"explanation":"Plasma glucose is measured at defined times after the oral glucose load.","explanationNe":"Oral glucose load पछि निश्चित समयमा plasma glucose मापन गरिन्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mock-021','BMLT','BMLT NHPC Licensing','mock','free',21,'{"question":"Which lipid is the main component of triglyceride-rich chylomicrons?","translation":"Triglyceride-rich chylomicron को मुख्य lipid कुन हो?","options":["Triglycerides","Free bilirubin","Phosphocreatine","Heme"],"correctIndex":0,"explanation":"Chylomicrons transport dietary triglycerides from the intestine.","explanationNe":"Chylomicron ले intestine बाट dietary triglyceride transport गर्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mock-022','BMLT','BMLT NHPC Licensing','mock','free',22,'{"question":"A sample with very high triglycerides may cause which appearance?","translation":"Triglyceride धेरै बढेको sample कस्तो देखिन सक्छ?","options":["Milky or lipemic","Clear water-like always","Green due to bilirubin","Black due to hemoglobin"],"correctIndex":0,"explanation":"Marked lipemia can make serum or plasma visibly turbid or milky.","explanationNe":"Lipemia धेरै भए serum वा plasma धमिलो वा दूधजस्तो देखिन सक्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mock-023','BMLT','BMLT NHPC Licensing','mock','free',23,'{"question":"Which enzyme helps convert triglycerides in lipoproteins into fatty acids?","translation":"Lipoprotein मा triglyceride लाई fatty acid मा बदल्न कुन enzyme सहयोग गर्छ?","options":["Lipoprotein lipase","Acetylcholinesterase","DNA polymerase","Renin"],"correctIndex":0,"explanation":"Lipoprotein lipase hydrolyzes triglycerides in chylomicrons and VLDL.","explanationNe":"Lipoprotein lipase ले chylomicron र VLDL को triglyceride hydrolysis गर्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
('bmlt-biochem2-mock-024','BMLT','BMLT NHPC Licensing','mock','free',24,'{"question":"Which condition is associated with increased unconjugated bilirubin due to hemolysis?","translation":"Hemolysis का कारण unconjugated bilirubin बढ्ने अवस्था कुन हो?","options":["Prehepatic jaundice","Obstructive jaundice only","Cholestasis only","Nephrotic syndrome"],"correctIndex":0,"explanation":"Increased red-cell breakdown produces more bilirubin before hepatic conjugation.","explanationNe":"Red cell breakdown बढ्दा liver conjugation अघि bilirubin बढी बन्छ।","topic":"Clinical Biochemistry"}'::jsonb,true),
