('bmlt-biochem2-mock-029','BMLT','BMLT NHPC Licensing','mock','free',29,'{"question":"Which clinical chemistry result should be promptly communicated if critically abnormal according to lab policy?","translation":"Lab policy अनुसार critical abnormal हुँदा कुन result तुरुन्त communicate गर्नुपर्छ?","options":["A critical value","Every normal result","Only instrument temperature","Only reagent lot number"],"correctIndex":0,"explanation":"Critical results require timely notification and documentation according to local policy.","explanationNe":"Critical result स्थानीय policy अनुसार समयमै notify र document गर्नुपर्छ।","topic":"Clinical Biochemistry"}'::jsonb,true)
